using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
namespace PZ3D {
 sealed class SteamVersionInstall {
  public string Id,SourceGame,Destination,Name,Stage,Message,SteamUri,PreservedVersionId,InstalledVersionId,Branch,BuildId,DetectedVersion;
  public int ExpectedMajor;public long BytesDone,BytesTotal;
 }
 // Steam owns branch selection and download. This journal observes that official step;
 // only a verified independent copy enters VersionLibrary as an installed version.
 sealed class SteamVersionWorkflow {
  public const string SteamGameUri="steam://nav/games/details/108600";
  readonly string data,game,user,journal,manifest;readonly VersionLibrary library;
  sealed class ManifestState {public string Hash,Branch,BuildId;public long Flags,Done,Total;}
  sealed class Vdf {
   readonly string text;int at;public Vdf(string value){text=value;}
   void Space(){while(at<text.Length){if(char.IsWhiteSpace(text[at])){at++;continue;}if(at+1<text.Length&&text[at]=='/'&&text[at+1]=='/'){while(at<text.Length&&text[at]!='\n')at++;continue;}break;}}
   string Quoted(){Space();if(at>=text.Length||text[at++]!='"')throw new IOException("Steam 清单文本无效。");var value=new StringBuilder();while(at<text.Length){char c=text[at++];if(c=='"')return value.ToString();if(c=='\\'){if(at>=text.Length)break;c=text[at++];if(c!='\\'&&c!='"')throw new IOException("Steam 清单转义无效。");}if(char.IsControl(c))throw new IOException("Steam 清单字段无效。");value.Append(c);}throw new IOException("Steam 清单文本不完整。");}
   Dictionary<string,object> Object(int depth,bool nested){if(depth>12)throw new IOException("Steam 清单嵌套过深。");var result=new Dictionary<string,object>(StringComparer.OrdinalIgnoreCase);while(true){Space();if(at==text.Length){if(nested)throw new IOException("Steam 清单缺少结束符。");return result;}if(text[at]=='}'){if(!nested)throw new IOException("Steam 清单结束符无效。");at++;return result;}string key=Quoted();if(result.ContainsKey(key))throw new IOException("Steam 清单字段重复。");Space();object value;if(at<text.Length&&text[at]=='{'){at++;value=Object(depth+1,true);}else value=Quoted();result.Add(key,value);if(result.Count>4096)throw new IOException("Steam 清单字段过多。");}}
   public Dictionary<string,object> Read(){return Object(0,false);}
  }
  public SteamVersionWorkflow(string dataRoot,string legacyGame,string legacyUser){data=VersionLibrary.Full(dataRoot);game=VersionLibrary.Full(legacyGame);user=VersionLibrary.Full(legacyUser);library=new VersionLibrary(data,game,user);journal=Path.Combine(data,"steam-version-install.json");string common=Path.GetDirectoryName(game),apps=common==null?null:Path.GetDirectoryName(common);manifest=common!=null&&apps!=null&&Path.GetFileName(common).Equals("common",StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(apps).Equals("steamapps",StringComparison.OrdinalIgnoreCase)?Path.Combine(apps,"appmanifest_108600.acf"):null;}
  static object Field(Dictionary<string,object> row,string key){object value;return row!=null&&row.TryGetValue(key,out value)?value:null;}
  static string Text(Dictionary<string,object> row,string key){return Field(row,key) as string??"";}
  static long Number(Dictionary<string,object> row,string key,bool optional=false){long value;string text=Text(row,key);if(optional&&text=="")return 0;if(!long.TryParse(text,System.Globalization.NumberStyles.None,System.Globalization.CultureInfo.InvariantCulture,out value)||value<0)throw new IOException("Steam 清单数字无效："+key);return value;}
  ManifestState ReadManifest(){if(manifest==null)throw new IOException("请先选择 Steam 正式库中的 Project Zomboid 安装。");VersionLibrary.Safe(manifest);if(!File.Exists(manifest)||new FileInfo(manifest).Length>1048576)throw new IOException("未找到有效的 Steam App108600 安装清单。");byte[] raw=File.ReadAllBytes(manifest);var outer=new Vdf(new UTF8Encoding(false,true).GetString(raw).TrimStart('\uFEFF')).Read();var app=Field(outer,"AppState") as Dictionary<string,object>;if(app==null||Text(app,"appid")!="108600"||Text(app,"installdir")!=Path.GetFileName(game))throw new IOException("Steam 清单与所选游戏安装不一致。");var config=Field(app,"UserConfig") as Dictionary<string,object>;string branch=Text(config,"BetaKey");return new ManifestState{Hash=DlssInstaller.Hash(raw),Flags=Number(app,"StateFlags"),BuildId=Text(app,"buildid"),Branch=branch==""?"public":branch,Done=Number(app,"BytesDownloaded",true),Total=Number(app,"BytesToDownload",true)};}
  static bool Ready(ManifestState manifest){return manifest.Flags==4&&!string.IsNullOrWhiteSpace(manifest.BuildId)&&manifest.BuildId.All(char.IsDigit)&&(manifest.Total==0||manifest.Done>=manifest.Total);}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=32768};}
  SteamVersionInstall Load(){VersionLibrary.Safe(journal);if(!File.Exists(journal))return null;if(new FileInfo(journal).Length>32768)throw new IOException("Steam 安装任务记录过大。");SteamVersionInstall job;try{job=Json().Deserialize<SteamVersionInstall>(File.ReadAllText(journal,Encoding.UTF8));}catch(Exception x){throw new IOException("Steam 安装任务记录损坏，已保留原文件。",x);}Guid id;if(job==null||!Guid.TryParseExact(job.Id,"N",out id)||job.SteamUri!=SteamGameUri||!VersionLibrary.Same(job.SourceGame,game)||(job.ExpectedMajor!=41&&job.ExpectedMajor!=42)||string.IsNullOrWhiteSpace(job.Destination)||!Path.IsPathRooted(job.Destination)||!(new[]{"awaiting-steam","downloading","ready-to-preserve","saved","cancelled","needs-check"}).Contains(job.Stage))throw new IOException("Steam 安装任务记录无效。");return job;}
  void Save(SteamVersionInstall job){VersionLibrary.Safe(data);Directory.CreateDirectory(data);VersionLibrary.Safe(journal);string temporary=journal+".new-"+Guid.NewGuid().ToString("N");try{File.WriteAllText(temporary,Json().Serialize(job),new UTF8Encoding(false));if(File.Exists(journal))File.Replace(temporary,journal,null);else File.Move(temporary,journal);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
  T Locked<T>(Func<T> action){using(var mutex=new Mutex(false,"Local\\OrangeSteamVersion-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(data.ToUpperInvariant())))){bool held=false;try{try{held=mutex.WaitOne(5000);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("另一个 Steam 版本任务仍在进行。");return action();}finally{if(held)mutex.ReleaseMutex();}}}
  SteamVersionInstall Observe(SteamVersionInstall job){if(job==null)return null;if(job.Stage=="saved"||job.Stage=="cancelled")return job;try{var installed=ReadManifest();var actual=GameVersionProbe.Read(game);job.Branch=installed.Branch;job.BuildId=installed.BuildId;job.BytesDone=installed.Done;job.BytesTotal=installed.Total;job.DetectedVersion=actual==null?"未知":actual.ToString();if(!Ready(installed)){job.Stage="downloading";job.Message="请在 Steam 中完成分支选择和下载；完成后刷新检查。";}else if(actual!=null&&actual.Major==job.ExpectedMajor){job.Stage="ready-to-preserve";job.Message="Steam 已完成所选版本安装，可保存为独立版本。";}else{job.Stage="awaiting-steam";job.Message="请在 Steam 游戏属性的“测试版”中选择 B"+job.ExpectedMajor+" 可用分支，等待下载完成。";}}catch(Exception x){job.Stage="needs-check";job.Message=x.Message;}return job;}
  public SteamVersionInstall State(){return Locked(()=>Observe(Load()));}
  public SteamVersionInstall BeginInteractive(int expectedMajor,string destination,string name,CancellationToken cancel,Action<VersionCopyProgress> progress=null){return Locked(()=>{
   if(expectedMajor!=41&&expectedMajor!=42)throw new IOException("请选择 B41 或 B42。");cancel.ThrowIfCancellationRequested();var old=Load();if(old!=null&&old.Stage!="saved"&&old.Stage!="cancelled")throw new IOException("已有 Steam 安装任务，请继续或取消后再创建。");string target=VersionLibrary.Full(destination);VersionLibrary.Safe(target);if(Directory.Exists(target)||File.Exists(target))throw new IOException("目标版本目录已存在，未覆盖。");var before=ReadManifest();if(!Ready(before))throw new IOException("Steam 当前安装尚未完成，请先等待下载结束。");var actual=GameVersionProbe.Read(game);if(actual==null)throw new IOException("无法核实当前游戏版本，未请求 Steam 更换分支。");string keep=target+"-before-"+actual+"-"+Guid.NewGuid().ToString("N").Substring(0,8);var preserved=library.PreserveChecked(game,keep,"切换前保留 "+actual,cancel,progress,()=>{if(ReadManifest().Hash!=before.Hash)throw new IOException("Steam 清单在保留期间改变，未继续安装。");});cancel.ThrowIfCancellationRequested();
   var job=new SteamVersionInstall{Id=Guid.NewGuid().ToString("N"),ExpectedMajor=expectedMajor,SourceGame=game,Destination=target,Name=name,SteamUri=SteamGameUri,PreservedVersionId=preserved.Id,Stage="awaiting-steam"};Observe(job);Save(job);return job;
  });}
  public LocalGameVersion Complete(CancellationToken cancel,Action<VersionCopyProgress> progress=null){return Locked(()=>{var job=Observe(Load());if(job==null||job.Stage!="ready-to-preserve")throw new IOException("请先在 Steam 完成所选版本下载，再刷新检查。");var before=ReadManifest();var result=library.PreserveChecked(game,job.Destination,job.Name,cancel,progress,()=>{var current=ReadManifest();var actual=GameVersionProbe.Read(game);if(current.Hash!=before.Hash||!Ready(current)||actual==null||actual.Major!=job.ExpectedMajor)throw new IOException("Steam 下载或版本在保存期间改变，请重试。");});job.InstalledVersionId=result.Id;job.Stage="saved";job.Message="已保存为独立版本，可在版本列表中选择启动。";Save(job);return result;});}
  public void Cancel(){Locked(()=>{var job=Load();if(job!=null&&job.Stage!="saved"){job.Stage="cancelled";job.Message="已取消跟踪；切换前保留的独立版本仍可使用。";Save(job);}return true;});}
 }
}
